INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('anti-aircraft', 11553, '1975-06-06', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/lugpuniuko65tknplcvj.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scq2k1.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Anti-Aircraft', 'Anti-Aircraft is a two-player arcade game by Atari, Inc, originally released in 1975. The game is sometimes referred to as Anti-Aircraft II, denoting the two-player aspect of the game. Planes fly overhead, either singly or in pairs, in random directions in the aircraft flight area. The object is to shoot down more planes than the player''s opponent during the time limit. Each player controls an anti-aircraft gun located in the lower left and right corners of the screen, respectively. A player''s gun is controlled by three buttons located in each player''s control station, which consists of a button for moving up, down, and firing. The up and down buttons move the gun to any one of three predefined positions.' FROM games WHERE igdb_id = 11553 ON CONFLICT (game_id, language_code) DO NOTHING;
