INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Flipper', 'Super Flipper is a pinball game that is more of a mix between Pong and Breakout. Using flipper buttons, which move side to side and further depending on how hard you press, you keep the ball in play to score as many points as possible. Originally made in Italy where it was known as UFO before being distributed by Chicago Coin as Super Flipper in the USA.' FROM games WHERE igdb_id = 110838 ON CONFLICT (game_id, language_code) DO NOTHING;
