INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Speed Race DX', 'The original Speed Race and Wheels had an upright arcade cabinet, while Midway''s Racer introduced a sit-down cabinet. Taito released an updated version of Speed Race called Speed Race DX in 1975. Speed Race DX is an updated version of Speed Race. The game plays mostly identical, with the player racing in a top-down view and gaining points for overtaking other cars. The cabinet is bigger and two new features have been added to the game with a gear shift lever and an in-game timer.' FROM games WHERE igdb_id = 342140 ON CONFLICT (game_id, language_code) DO NOTHING;
