INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bullet Mark', 'A light gun game by Sega released in 1975. The unweildy cabinet proved unpopular with distributors, leading to the development of a scaled-down version called Tracer in 1976. This game was the first Sega game to be produced in America.' FROM games WHERE igdb_id = 171851 ON CONFLICT (game_id, language_code) DO NOTHING;
