INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Avenger', 'The game has a top-down view of a aircraft scene. Your fighter is at the bottom and you control its speed and horizontal position with the joystick. The scene scrolls from top to bottom and enemy aircraft appear at top of screen, flying down towards you. The Afterburner button lets you quickly speed up.' FROM games WHERE igdb_id = 91358 ON CONFLICT (game_id, language_code) DO NOTHING;
