INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crash ''N Score', 'Crash ''N Score is a 2 player arcade game by Atari Inc., originally released in 1975. Gameplay is a simulation of a demolition derby, in which players compete by smashing each other and running over randomly appearing numbered flags within an allotted time. Players can choose to play with or without barriers.' FROM games WHERE igdb_id = 11554 ON CONFLICT (game_id, language_code) DO NOTHING;
