INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shark', 'You control a shark who must swim through a maze of shark traps and nets and attack a swimmer before she reaches the shoreline. The first shark to eat five swimmers wins.' FROM games WHERE igdb_id = 110852 ON CONFLICT (game_id, language_code) DO NOTHING;
