INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('panther--2', 291106, '1975-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7w06.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scr4az.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Panther', 'Panther, a battle tank-driving simulation named after the Panther tank, was one of a handful of early first-person computer games developed by John Edo Haefeli and Nelson Bridwell in 1975 at Northwestern University. The game was developed for the multi-user interactive computer-based education PLATO system and programmed in the TUTOR programming language and utilized scalable vector graphics called linesets. A 1977 development of Panther, with more refined graphics, was named Panzer. The game features team-based deathmatch. There are two teams, Squares and Triangles. The object of the game is to destroy the opposing team''s base. Game play is straightforward; the player selects a pseudonym and a team, traverse the terrain looking for enemies to destroy on the way to their base. Perspective is maintained by the use of scalable vector graphics and visual interest is enhanced with special graphics for explosions using a custom character set to accomplish limited raster graphics animation. When players enter the game their tanks are placed randomly in the playing arena near their bases and are temporarily camouflaged to allow time to orient themselves with the current map and state of play. The initial view of the game is in "on-board" mode, which is a first-person perspective of the arena. The other main view available is the map which shows the 5 mountains (Crag, Nixon, Og, Pathos, and Red) which vary in size and placement each time a new game is started. On the map view players can see all of their team members positions and can see enemies only when they are within range. Messaging between team members is available and broadcast-style messages (insults) to the opposing team are also allowed. Team coordination and cooperation is critical to winning in this game as each player has different skills, some players are better at hunting down and killing enemies (or at least engaging and distracting them), others are good at hiding and sneaking to the opposing base to begin bombardment. An interesting capability of the game is that players can donate ammunition and fuel to other players in order to facilitate their role in the game. Ammunition and fuel are loaded at the player''s base.' FROM games WHERE igdb_id = 291106 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 291106 AND ge.slug = 'simulator' ON CONFLICT DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 291106 AND p.igdb_id = 110 ON CONFLICT DO NOTHING;
